            function fileToDataUrl(file,maxDim,quality){return new Promise(function(resolve,reject){if(!file){reject(new Error('未选择文件'));return;}if(!file.type||file.type.indexOf('image/')!==0){reject(new Error('请选择图片文件'));return;}if(file.type==='image/gif'){var rg=new FileReader();rg.onload=function(){resolve(String(rg.result||''));};rg.onerror=function(){reject(new Error('读取GIF失败'));};rg.readAsDataURL(file);return;}var reader=new FileReader();reader.onload=function(e){var orig=String(e.target&&e.target.result||'');var img=new Image();img.onload=function(){try{var w=img.naturalWidth||img.width,h=img.naturalHeight||img.height,sc=1;if(maxDim&&(w>maxDim||h>maxDim))sc=Math.min(maxDim/w,maxDim/h);var cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(w*sc));cv.height=Math.max(1,Math.round(h*sc));var c=cv.getContext('2d');if(!c){resolve(orig);return;}if(file.type==='image/png'){c.clearRect(0,0,cv.width,cv.height);c.drawImage(img,0,0,cv.width,cv.height);var png=cv.toDataURL('image/png');if(png.length>2*1024*1024){c.fillStyle='#fff';c.fillRect(0,0,cv.width,cv.height);c.drawImage(img,0,0,cv.width,cv.height);resolve(cv.toDataURL('image/jpeg',quality||0.85));}else{resolve(png);}}else{c.drawImage(img,0,0,cv.width,cv.height);resolve(cv.toDataURL('image/jpeg',quality||0.85));}}catch(err){resolve(orig);}};img.onerror=function(){reject(new Error('图片加载失败'));};img.src=orig;};reader.onerror=function(){reject(new Error('读取文件失败'));};reader.readAsDataURL(file);});}
            function setVueInputValue(input,value){if(!input)return;var doc=input.ownerDocument||document,win=doc.defaultView||window;var proto=input.tagName==='TEXTAREA'?win.HTMLTextAreaElement:win.HTMLInputElement;var setter=null;try{setter=Object.getOwnPropertyDescriptor(proto.prototype,'value').set;}catch(e){}if(setter){setter.call(input,value);}else{input.value=value;}try{input.dispatchEvent(new win.Event('input',{bubbles:true}));input.dispatchEvent(new win.Event('change',{bubbles:true}));}catch(e){input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));}}
