            function bindUploadBtn(btn,urlInput,maxDim,msg){btn.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();var orig=btn.innerHTML;pickImageFile(false,function(files){if(!files||!files[0])return;btn.innerHTML='<i class="fas fa-spinner fa-spin"></i><span>处理中...</span>';fileToDataUrl(files[0],maxDim||512,0.85).then(function(url){setVueInputValue(urlInput,url);showToast(msg||'图片已上传');btn.innerHTML='<i class="fas fa-check"></i><span>已上传</span>';setTimeout(function(){btn.innerHTML=orig;},2000);}).catch(function(err){showToast(err.message||'失败',true);btn.innerHTML=orig;});});});}
            function injectDialogUpload(){if(!phoneCtx)return;var root=phoneCtx.root;var inputs=root.querySelectorAll('input[placeholder="输入表情包图片链接"],input[placeholder="输入图片链接"]');for(var i=0;i<inputs.length;i++){var urlInput=inputs[i];var dialog=urlInput.closest('.dialog-overlay');if(!dialog||dialog.getAttribute(UPLOAD_ATTR))continue;var title=dialog.querySelector('.dialog-title,span');if(title&&title.textContent.indexOf('编辑')!==-1)continue;dialog.setAttribute(UPLOAD_ATTR,'1');var wrapper=urlInput.parentElement;if(!wrapper)continue;var btn=phoneCtx.doc.createElement('button');btn.type='button';btn.className='pe-upload-btn';btn.innerHTML='<i class="fas fa-folder-open"></i><span>本地上传</span>';bindUploadBtn(btn,urlInput,512,'图片已上传，请填写名称');if(wrapper.nextSibling){wrapper.parentNode.insertBefore(btn,wrapper.nextSibling);}else{wrapper.parentNode.appendChild(btn);}}}
            function injectPickerUpload(){if(!phoneCtx)return;var root=phoneCtx.root;var modals=root.querySelectorAll('.image-picker-modal');for(var i=0;i<modals.length;i++){var modal=modals[i];if(modal.getAttribute(UPLOAD_ATTR))continue;modal.setAttribute(UPLOAD_ATTR,'1');var row=modal.querySelector('.image-picker-input-row');var urlInput=modal.querySelector('.image-picker-input');if(!row||!urlInput)continue;var btn=phoneCtx.doc.createElement('button');btn.type='button';btn.className='pe-upload-btn';btn.style.width='44px';btn.style.flexShrink='0';btn.innerHTML='<i class="fas fa-folder-open"></i>';btn.title='本地上传';bindUploadBtn(btn,urlInput,800,'图片已上传');row.appendChild(btn);}var urlModals=root.querySelectorAll('.url-input-modal');for(var j=0;j<urlModals.length;j++){var um=urlModals[j];if(um.getAttribute(UPLOAD_ATTR))continue;um.setAttribute(UPLOAD_ATTR,'1');var uInput=um.querySelector('.url-input-field');var uBody=um.querySelector('.url-input-body');if(!uInput||!uBody)continue;var uBtn=phoneCtx.doc.createElement('button');uBtn.type='button';uBtn.className='pe-upload-btn';uBtn.innerHTML='<i class="fas fa-folder-open"></i><span>本地上传</span>';bindUploadBtn(uBtn,uInput,800,'图片已上传');uBody.appendChild(uBtn);}}
            function loadWallpapers(){wallpapers=getVar(VAR_WALLPAPERS,[]);if(!Array.isArray(wallpapers))wallpapers=[];wpIndex=getVar(VAR_WALLPAPER_IDX,0);if(typeof wpIndex!=='number'||wpIndex<0||wpIndex>=wallpapers.length)wpIndex=0;}
