            function injToolbar(){try{var doc=activeDoc||document;if(doc.getElementById('cm-toolbar-btn'))return;var btn=doc.createElement('button');btn.id='cm-toolbar-btn';btn.innerHTML='<i class="fas fa-home"></i> 住户管理';btn.title='打开住户管理 (Ctrl+Shift+C)';btn.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();togglePanel();});var sb=doc.getElementById('send_but')||doc.querySelector('button[id*="send"]');if(sb&&sb.parentNode){sb.parentNode.style.position=sb.parentNode.style.position||'relative';sb.parentNode.appendChild(btn);}else{doc.body.appendChild(btn);}}catch(e){}}
            function init(){if(window[IF])return true;try{activeDoc=detDoc();if(!activeDoc||!activeDoc.body){console.warn('[CM] 未找到活动document');return false;}window[IF]=true;loadAll();injStyle();createFab();createPanel();injToolbar();activeDoc.addEventListener('keydown',function(e){if(e.ctrlKey&&e.shiftKey&&(e.key==='C'||e.key==='c')){e.preventDefault();togglePanel();}});expGlobals(togglePanel);console.log('[TenantManager] v1.0 已加载 | 触发:浮窗/底部按钮/手机APP/Ctrl+Shift+C/openCM()');return true;}catch(e){console.error('[CM] 初始化失败:',e);window[IF]=false;return false;}}
