            function start(){function ti(){if(!window[IF])init();}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',ti);}else{ti();}[100,300,800,1500,2500,4000,6000,10000,15000,20000].forEach(function(d){setTimeout(function(){if(!window[IF])ti();else ensureFab();},d);});setInterval(ensureFab,3000);try{var ds=gDocs();for(var i=0;i<ds.length;i++){if(ds[i].body){new MutationObserver(function(){if(!window[IF])ti();else ensureFab();}).observe(ds[i].body,{childList:true,subtree:false});}}}catch(e){}}
